const e=JSON.parse('{"key":"v-55d1be45","path":"/ACM-docs/%E5%8A%A8%E6%80%81%E8%A7%84%E5%88%92/%E6%95%B0%E4%BD%8DDP.html","title":"数位DP","lang":"zh-CN","frontmatter":{"summary":"数位DP 引入 数位是指把一个数字按照个、十、百、千等等一位一位地拆开，关注它每一位上的数字。如果拆的是十进制数，那么每一位数字都是 $0~9$，其他进制可类比十进制。 数位 $DP$：用来解决一类特定问题，这种问题比较好辨认，一般具有这几个特征： 1. 要求统计满足一定条件的数的数量（即，最终目的为计数）； 1. 这些条件经过转化后可以使用「数位」的思想去","head":[["meta",{"property":"og:url","content":"https://ClearDewy.github.io/ACM-docs/%E5%8A%A8%E6%80%81%E8%A7%84%E5%88%92/%E6%95%B0%E4%BD%8DDP.html"}],["meta",{"property":"og:site_name","content":"Dewy-Wiki"}],["meta",{"property":"og:title","content":"数位DP"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:updated_time","content":"2022-10-28T15:56:16.000Z"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"article:modified_time","content":"2022-10-28T15:56:16.000Z"}]]},"excerpt":"","headers":[{"level":2,"title":"引入","slug":"引入","link":"#引入","children":[]}],"git":{"createdTime":1666442862000,"updatedTime":1666972576000,"contributors":[{"name":"Qingtuan","email":"2233408834@qq.com","commits":2}]},"readingTime":{"minutes":1.26,"words":377},"filePathRelative":"ACM-docs/动态规划/数位DP.md","localizedDate":"2022年10月22日"}');export{e as data};
